import{_ as e,o as t,c as i,ag as a}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"How to add config file","description":"","frontmatter":{},"headers":[],"relativePath":"qa/add-config.md","filePath":"qa/add-config.md","lastUpdated":1786673734000}'),r={name:"qa/add-config.md"};function n(s,o,l,c,d,p){return t(),i("div",null,[...o[0]||(o[0]=[a(`<h1 id="how-to-add-config-file" tabindex="-1">How to add config file <a class="header-anchor" href="#how-to-add-config-file" aria-label="Permalink to &quot;How to add config file&quot;">​</a></h1><p>EasyYapi supports multiple ways to add configuration files to your project.</p><h2 id="option-1-project-root-directory" tabindex="-1">Option 1: Project root directory <a class="header-anchor" href="#option-1-project-root-directory" aria-label="Permalink to &quot;Option 1: Project root directory&quot;">​</a></h2><p>Create a <code>.easy.api.config</code> file in the project root directory (the folder you opened in the IDE):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── .easy.api.config</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>└── pom.xml</span></span></code></pre></div><blockquote><p><strong>Multi-module projects note:</strong> There is no module-level configuration layer. Rule files are resolved only from the project root directory; the discovery process does not recurse into subdirectories. If you open the parent directory as the project, configuration files placed in subdirectories such as <code>module-a/</code> will not be loaded. If you want a module to have its own rules, open that module folder as a separate project.</p></blockquote><h2 id="option-2-remote-configuration" tabindex="-1">Option 2: Remote configuration <a class="header-anchor" href="#option-2-remote-configuration" aria-label="Permalink to &quot;Option 2: Remote configuration&quot;">​</a></h2><p>Configure remote config URLs in <strong>Settings → EasyApi → Rules → Remote</strong>. You can also pull remote configs from within a rule file using the <code>###include</code> directive.</p><p>See <a href="/settings/remote-config">Remote Config File</a> for details.</p><h2 id="configuration-priority" tabindex="-1">Configuration priority <a class="header-anchor" href="#configuration-priority" aria-label="Permalink to &quot;Configuration priority&quot;">​</a></h2><ol><li>Project rules (<code>.easyapi/</code> or <code>.easy.api.config*</code> in the project root) — highest priority</li><li>Extension rules (built-in framework presets)</li><li>Remote configuration</li><li>Global rules (<code>~/.easyapi/</code>) — lowest priority</li></ol><p>See <a href="/settings/local-file-config">Local Config File</a> and <a href="/settings/remote-config">Remote Config File</a>.</p>`,12)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
